using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class CurveScaleCheck {
 internal static int Run(string input,string output){var row=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray().Single(r=>r!["fault"]!.GetValue<string>()=="control")!.AsObject();string root=row["root"]!.GetValue<string>(),id=row["executionId"]!.GetValue<string>(),sha=row["executionSha256"]!.GetValue<string>();var refs=row["references"]!.AsObject();var proof=SolidScaleProof.Preparation(root,refs,false,true);_=SolidScaleProof.Execution(root,id,sha,false,false,true);int cases=2;
  var packet=ArtifactProof.Verified(root,"ownedscales",refs["ownedScaleId"]!.GetValue<string>(),refs["ownedScaleSha256"]!.GetValue<string>(),65536);var bundle=ArtifactProof.Verified(root,"curvescalebundles",refs["ownedScaleId"]!.GetValue<string>(),refs["membershipBundleSha256"]!.GetValue<string>(),16000000);var source=ArtifactProof.Verified(root,"responses",packet["bindingInspectionRequestId"]!.GetValue<string>(),packet["bindingInspectionSha256"]!.GetValue<string>(),16000000);var args=row["verificationArguments"]!;var after=ArtifactProof.Verified(root,"responses",args["inspectionRequestId"]!.GetValue<string>(),args["inspectionSha256"]!.GetValue<string>(),16000000);var result=row["verificationResult"]!;var diagnostic=ArtifactProof.Verified(root,"curvescaleverifications",row["verificationId"]!.GetValue<string>(),result["diagnosticSha256"]!.GetValue<string>(),16000000);var def=UniformScaleDefinition.Read(packet["parameters"]!.AsObject());CurveScaleWitnessProof.Diagnostic(source,after,bundle["measurement"]!.AsObject(),def,diagnostic);cases++;
  foreach(string fault in new[]{"point","direction","magnitude","flag","solid","area","raw_sha","legacy_type"}){bool rejected=false;try{if(fault=="raw_sha")_=SolidScaleProof.Execution(root,id,new string('f',64),false,false,true);else if(fault=="legacy_type")_=SolidScaleProof.Preparation(root,refs);else{var d=diagnostic.DeepClone().AsObject();var o=after.DeepClone().AsObject();if(fault=="area")o["entities"]![1]!["geometry"]!["areaRaw"]=999;else if(fault=="solid")o["entities"]![0]!["geometry"]!["cogRaw"]![0]=999;else{int field=fault=="direction"?1:fault=="magnitude"?2:fault=="flag"?3:0;d["captureAfter"]!["layout"]!["fields"]![field]!["values"]![0]=fault=="flag"?JsonValue.Create(true):JsonValue.Create(999);}CurveScaleWitnessProof.Diagnostic(source,o,bundle["measurement"]!.AsObject(),def,d);}}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException("Curve scale forged proof accepted: "+fault);cases++;}
  foreach(var partial in JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray().Where(r=>new[]{"phase0","phase10","phase12"}.Contains(r!["fault"]!.GetValue<string>()))){string folder=partial!["root"]!.GetValue<string>(),execution=partial["executionId"]!.GetValue<string>();var original=SolidScaleProof.Raw(folder,execution);bool rejected=false;try{_=SolidScaleProof.Execution(folder,execution,original.Sha,false,false,true);}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException("Incomplete curve scale phases accepted");cases++;}
  Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: {cases} actual Framework curve scale receipts/phase-chain/SDK witnesses; no CAD.");return 0;
 }
}
